"""The personal agents an owner shows on a bot's page: their names and product marks.

An owner may list the agents they use with Yobiru; the card stores their ids (`agents`) and the page shows each with
its mark, the first one also on the picture. The list is what the owner says, like the links: the gateway does not
check it, and the private host kind of a native binding is never copied into it.

The marks are monochrome product logos from Simple Icons (CC0 1.0, https://simpleicons.org) and Lobe Icons (MIT,
https://github.com/lobehub/lobe-icons, notice below); Grok Bot's is the mark on its own page (x.ai/bot), and Muse's
the Muse Platform icon (platform.muse.ai), as pinku.chat draws it. Each mark belongs to its owner; it only says which
product an owner uses. Pure functions only (stdlib): used by the gateway (checks, the page) and the client (names
people type).
"""
import re

MAX_AGENTS = 8

# (id, name, other names people use for it). The names are the products' own; `named` ignores case, spaces, hyphens
# and underscores, so "Claude Code", "claude-code" and "claude_code" are one agent.
AGENTS = (
    ("grok", "Grok Bot", "grok, xai, grok agent"),
    ("muse", "Muse", "meta muse, meta"),
    ("claude", "Claude", "anthropic, claude ai, claude app"),
    ("claude_code", "Claude Code", "claude cli"),
    ("chatgpt", "ChatGPT", "openai, chatgpt agent, gpt"),
    ("codex", "Codex", "openai codex, codex cli"),
    ("gemini", "Gemini", "google gemini, gemini cli, gemini agent"),
    ("cursor", "Cursor", "cursor agent"),
    ("opencode", "OpenCode", ""),
    ("openclaw", "OpenClaw", "clawdbot, moltbot"),
    ("hermes", "Hermes Agent", "hermes, nous hermes"),
    ("manus", "Manus", ""),
    ("perplexity", "Perplexity", "comet, perplexity comet"),
    ("copilot", "GitHub Copilot", "copilot"),
    ("windsurf", "Windsurf", ""),
    ("cline", "Cline", ""),
    ("kimi", "Kimi", "moonshot, kimi k2"),
    ("doubao", "豆包", "doubao"),
    ("qwen", "Qwen", "通义, 通义千问, 千问, tongyi"),
    ("deepseek", "DeepSeek", ""),
)
IDS = tuple(a[0] for a in AGENTS)
NAMES = dict((a[0], a[1]) for a in AGENTS)


def _key(text):
    return re.sub(r"[\s_-]+", "", (text or "").strip().lower())


_BY_NAME = dict([(_key(a[0]), a[0]) for a in AGENTS] + [(_key(a[1]), a[0]) for a in AGENTS] +
                [(_key(alias), a[0]) for a in AGENTS for alias in a[2].split(",") if alias.strip()])


def named(text):
    """An agent id from a name people use for it ("Claude Code", "grok bot", "通义千问"), else None."""
    return _BY_NAME.get(_key(text))


def clean(value):
    """An owner's agent list: up to MAX_AGENTS distinct ids from AGENTS, in the owner's order. Returns the list or
    raises ValueError with a short reason."""
    if not isinstance(value, list) or len(value) > MAX_AGENTS:
        raise ValueError("agents: a list of at most %d agent ids" % MAX_AGENTS)
    for aid in value:
        if not isinstance(aid, str) or aid not in NAMES:
            raise ValueError("agents: unknown agent %r; known: %s" % (str(aid)[:40], ", ".join(IDS)))
    if len(set(value)) != len(value):
        raise ValueError("agents: each agent once")
    return list(value)


def mark(aid):
    """(viewBox, fill rule, paths, faint) of an agent's mark: `faint` holds the indexes of the paths drawn at half
    opacity."""
    return (_VIEWBOX.get(aid, "0 0 24 24"),) + _MARKS[aid]


